    views.summary=makeView('summary',SummaryView.markup());
    views.metrics=makeView('metrics',`<header class="shell-page-head"><span class="shell-eyebrow">Resultados del evento</span><h1>Decisiones con datos reales.</h1><p>Conecta la venta de entradas de PASSLINK con la operación de T-Show, sin exponer información personal de compradores.</p></header><article class="glass-panel shell-projects metrics-connect"><div class="panel-title"><div><span class="shell-eyebrow">Integración</span><h2>PASSLINK</h2></div><button class="btn btn-secondary" id="metricsRefresh" type="button">Actualizar</button></div><p id="metricsStatus" class="shell-muted" role="status">Consultando conexión…</p><div id="ticketeraConnector" class="ticketera-connector"></div></article><section id="metricsDashboard" class="metrics-dashboard" hidden aria-live="polite"><div class="metric-card"><span>Entradas emitidas</span><strong id="metricIssued">0</strong><small id="metricChecked">0 acreditadas</small></div><div class="metric-card"><span>Ingresos aprobados</span><strong id="metricRevenue">$0</strong><small id="metricPayments">0 ventas</small></div><div class="metric-card"><span>Ocupación</span><strong id="metricOccupancy">0%</strong><small id="metricCapacity">Sin aforo definido</small></div><div class="metric-card"><span>Por acreditar</span><strong id="metricPending">0</strong><small>Entradas aún no utilizadas</small></div><article class="glass-panel metric-breakdown"><div class="panel-title"><div><span class="shell-eyebrow">Distribución</span><h2>Entradas por tipo</h2></div></div><div id="metricTicketTypes" class="metric-bars"></div></article><article class="glass-panel metric-breakdown"><div class="panel-title"><div><span class="shell-eyebrow">Accesos</span><h2>Entradas por zona</h2></div></div><div id="metricZones" class="metric-bars"></div></article></section>`);
    views.team=makeView('team',`<header class="shell-page-head"><span class="shell-eyebrow">Equipo</span><h1>Cada persona.<br>Solo lo necesario.</h1><p>Invita, asigna responsabilidades y protege la operación con permisos claros por proyecto.</p></header><article class="glass-panel shell-projects"><div class="panel-title"><div><span class="shell-eyebrow">Accesos</span><h2>Miembros actuales</h2></div><button class="btn btn-primary" id="shellInvite">Invitar persona</button></div><p id="shellTeamStatus" class="shell-muted">Cargando equipo…</p><div id="shellMembers" class="team-list"></div></article><article class="glass-panel shell-projects team-invitations"><div class="panel-title"><div><span class="shell-eyebrow">Pendientes</span><h2>Invitaciones</h2></div></div><div id="shellInvitations" class="team-list"></div></article>`);
    views.files=makeView('files',window.ProjectFiles.markup());
