  async function loadProjects(){const result=await ApiClient.getAllProjects();projectsCache=Object.values(result.data||{});projectsMeta=result.meta||projectsMeta;return result;}
  async function attachCover(card,project){if(!project.coverKey)return;try{const signed=await ApiClient.signedFileUrl(project.coverKey);card.style.setProperty('--cover-image',`url("${String(signed.url).replace(/"/g,'%22')}")`);card.classList.add('has-cover');}catch(_){} }
  function projectCard(project,index){const article=document.createElement('article');article.className=`project-card accent-${project.accentColor||'blue'}`;article.tabIndex=0;article.dataset.projectId=project.id;article.setAttribute('role','button');article.setAttribute('aria-label',`Abrir ${project.eventName}`);article.innerHTML=`<div class="project-card-art"><span class="project-card-index">${String(index+1).padStart(2,'0')}</span>${canManage(project)?`<button class="project-menu-button" type="button" aria-label="Opciones de ${esc(project.eventName)}" aria-expanded="false">•••</button><div class="project-menu" hidden><button type="button" data-project-action="edit">Editar identidad</button><button type="button" data-project-action="duplicate">Duplicar proyecto</button><button type="button" data-project-action="delete">Eliminar proyecto</button></div>`:''}<div class="project-card-copy"><span>${esc(typeLabels[project.projectType]||'Proyecto')}</span><h2>${esc(project.eventName||'Proyecto sin nombre')}</h2><p>${esc(project.location||'Ubicación por definir')}</p></div></div><footer><span>${dateLabel(project.eventDate)}</span><strong>${roleLabel(project.permission)}</strong></footer>`;attachCover(article,project);return article;}
  function createCard(){const article=document.createElement('article');const available=projectsMeta.remaining===null||projectsMeta.remaining>0;article.className=`project-card create-project-card${available?'':' is-disabled'}`;article.tabIndex=available?0:-1;article.dataset.createProject='true';article.setAttribute('role','button');if(!available)article.setAttribute('aria-disabled','true');article.setAttribute('aria-label',available?'Crear evento':'Cupo de eventos alcanzado');article.innerHTML=`<div class="create-project-content"><span class="create-symbol" aria-hidden="true">${available?'+':'—'}</span><h2>${available?'Crear evento':'Cupo alcanzado'}</h2><p>${available?'Abre un nuevo espacio para tu próxima producción.':'Activa un plan para crear más eventos.'}</p></div>`;return article;}

  async function loadProjectSelector(){
    const carousel=document.getElementById('projectCarousel'),quota=document.getElementById('projectQuota');if(!carousel)return;
    document.querySelector('.project-selector-stage')?.classList.remove('is-exiting');
    try{await loadProjects();const limitLabel=projectsMeta.limit===null?'ilimitados':projectsMeta.limit;quota.textContent=`${projectsMeta.ownedCount} de ${limitLabel} eventos propios · Plan ${projectsMeta.plan||'free'}`;carousel.innerHTML='';projectsCache.forEach((project,index)=>carousel.appendChild(projectCard(project,index)));const create=document.getElementById('createProjectAction');const available=projectsMeta.remaining===null||projectsMeta.remaining>0;if(create){create.disabled=!available;create.setAttribute('aria-disabled',String(!available));create.querySelector('span:last-child').textContent=available?'Crear evento':'Cupo alcanzado';}updateProjectGridLayout();requestAnimationFrame(()=>updateCarouselFocus());}
    catch(error){quota.textContent='No pudimos sincronizar';carousel.innerHTML=`<div class="shell-message" data-status="error">${esc(error.message)}</div>`;}
  }
  function updateCarouselFocus(){const carousel=document.getElementById('projectCarousel');if(!carousel)return;const cards=[...carousel.querySelectorAll('.project-card')];const status=document.getElementById('projectPageStatus'),prev=document.querySelector('.carousel-prev'),next=document.querySelector('.carousel-next');if(matchMedia('(max-width:767px)').matches||!cards.length){cards.forEach(card=>card.classList.remove('is-focused'));if(status)status.textContent='';if(prev)prev.hidden=true;if(next)next.hidden=true;return;}const style=getComputedStyle(carousel);const pageSize=Number(style.getPropertyValue('--project-page-size'))||1;const totalPages=Math.max(1,Math.ceil(cards.length/pageSize));const maxScroll=Math.max(0,carousel.scrollWidth-carousel.clientWidth);const starts=Array.from({length:totalPages},(_,page)=>Math.min(cards[Math.min(page*pageSize,cards.length-1)].offsetLeft,maxScroll));let page=0;starts.forEach((start,index)=>{if(Math.abs(start-carousel.scrollLeft)<Math.abs(starts[page]-carousel.scrollLeft))page=index;});page+=1;cards.forEach(card=>card.classList.remove('is-focused'));if(status){status.hidden=totalPages<=1;status.textContent=totalPages>1?`Página ${page} de ${totalPages}`:'';}if(prev){prev.hidden=totalPages<=1;prev.disabled=page<=1;}if(next){next.hidden=totalPages<=1;next.disabled=page>=totalPages;}}
  function updateProjectGridLayout(){
    const carousel=document.getElementById('projectCarousel');if(!carousel)return;
    const width=window.innerWidth;
    const previousPage=Number(document.getElementById('projectPageStatus')?.textContent.match(/Página (\d+)/)?.[1]||1);
    const pageSize=width<768?3:width<1024?2:3;
    carousel.style.setProperty('--project-page-size',String(pageSize));
    carousel.classList.remove('is-dense');
    carousel.tabIndex=width<768?-1:0;
    requestAnimationFrame(()=>{if(width>=768&&carousel.scrollWidth>carousel.clientWidth){const pageSize=Number(getComputedStyle(carousel).getPropertyValue('--project-page-size'))||1;const cards=[...carousel.querySelectorAll('.project-card')];const target=cards[Math.min((previousPage-1)*pageSize,cards.length-1)];carousel.scrollLeft=Math.min(target?.offsetLeft||0,Math.max(0,carousel.scrollWidth-carousel.clientWidth));}updateCarouselFocus();});
  }
  function moveCarousel(direction){if(matchMedia('(max-width:767px)').matches)return;const carousel=document.getElementById('projectCarousel');if(!carousel)return;const cards=[...carousel.querySelectorAll('.project-card')];const pageSize=Number(getComputedStyle(carousel).getPropertyValue('--project-page-size'))||1;const totalPages=Math.max(1,Math.ceil(cards.length/pageSize));const current=Number(document.getElementById('projectPageStatus')?.textContent.match(/Página (\d+)/)?.[1]||1);const targetPage=Math.max(1,Math.min(totalPages,current+direction));const target=cards[Math.min((targetPage-1)*pageSize,cards.length-1)];const maxScroll=Math.max(0,carousel.scrollWidth-carousel.clientWidth);carousel.scrollTo({left:Math.min(target?.offsetLeft||0,maxScroll),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});setTimeout(updateCarouselFocus,matchMedia('(prefers-reduced-motion: reduce)').matches?0:300);}
  async function openProject(project){
    const stage=document.querySelector('.project-selector-stage');
    const card=[...document.querySelectorAll('.project-card')].find(node=>node.dataset.projectId===project.id);
    card?.classList.add('is-selected');
    stage?.classList.add('is-exiting');
    currentProject=project.id;currentProjectData=project;currentProjectName=project.eventName;applyProjectIdentity(project);
    try{await window.app?.loadProject(project.id);navigate('summary',true);}catch(error){currentProject='';currentProjectData=null;currentProjectName='Elige tu evento';stage?.classList.remove('is-exiting');const quota=document.getElementById('projectQuota');if(quota){quota.dataset.status='error';quota.textContent='Este evento ya no está disponible. Selecciona otro.';}await navigate('projects',true);}
  }

  function openWizard(mode,project=null){wizardMode=mode;wizardProject=project;wizardStep=1;const modal=document.getElementById('projectWizard'),form=document.getElementById('projectWizardForm');form.reset();document.getElementById('wizardName').value=project?.eventName||'';document.getElementById('wizardType').value=project?.projectType||'concert';document.getElementById('wizardDate').value=project?.eventDate||'';document.getElementById('wizardLocation').value=project?.location||'';const accent=project?.accentColor||'blue';const radio=form.querySelector(`[name="accent"][value="${accent}"]`);if(radio)radio.checked=true;document.getElementById('wizardSave').textContent=mode==='edit'?'Guardar identidad':'Crear proyecto';document.getElementById('wizardStatus').hidden=true;setWizardStep(1);updateWizardPreview();modal.hidden=false;document.body.classList.add('modal-open');setTimeout(()=>document.getElementById('wizardName').focus(),40);}
  function closeWizard(){document.getElementById('projectWizard').hidden=true;document.body.classList.remove('modal-open');if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl='';}}
  function setWizardStep(step){wizardStep=step;document.querySelectorAll('.wizard-step').forEach(node=>node.hidden=Number(node.dataset.step)!==step);document.getElementById('wizardBack').hidden=step===1;document.getElementById('wizardNext').hidden=step===2;document.getElementById('wizardSave').hidden=step===1;document.getElementById('wizardKicker').textContent=`${wizardMode==='edit'?'Editar identidad':'Nuevo proyecto'} · Paso ${step} de 2`;document.getElementById('wizardTitle').textContent=step===1?'Dale nombre al evento.':'Hazlo reconocible.';}
  function wizardIdentity(){return{eventName:document.getElementById('wizardName').value.trim(),projectType:document.getElementById('wizardType').value,eventDate:document.getElementById('wizardDate').value,location:document.getElementById('wizardLocation').value.trim(),accentColor:document.querySelector('[name="accent"]:checked')?.value||'blue'};}
  function updateWizardPreview(){const identity=wizardIdentity(),preview=document.getElementById('wizardPreview');preview.className=`project-preview accent-${identity.accentColor}`;document.getElementById('wizardPreviewName').textContent=identity.eventName||'Tu próximo evento';document.getElementById('wizardPreviewType').textContent=(typeLabels[identity.projectType]||'Proyecto').toUpperCase();if(previewUrl)preview.style.backgroundImage=`linear-gradient(180deg,transparent,rgba(2,4,10,.78)),url("${previewUrl}")`;}
    async function uploadCover(projectId,file){if(!file)return null;if(file.size>10*1024*1024)throw new Error('La portada supera el máximo de 10 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Usa una imagen JPEG, PNG o WebP.');const signed=await Auth.api('/api/uploads/sign',{method:'POST',body:JSON.stringify({category:'cover',projectId,filename:file.name,contentType:file.type,size:file.size})});const upload=await fetch(signed.uploadUrl,{method:'PUT',headers:{'Content-Type':file.type},body:file});if(!upload.ok)throw new Error('No se pudo cargar la portada.');const finalized=await Auth.api(`/api/uploads/${encodeURIComponent(signed.uploadId)}/finalize`,{method:'POST'});return finalized.data.object_key;}
  async function saveWizard(event){event.preventDefault();const status=document.getElementById('wizardStatus'),save=document.getElementById('wizardSave'),identity=wizardIdentity(),file=document.getElementById('wizardCover').files[0];if(!identity.eventName){setWizardStep(1);document.getElementById('wizardName').focus();return;}status.hidden=false;status.dataset.status='warning';status.textContent='Guardando identidad…';save.disabled=true;save.setAttribute('aria-busy','true');try{let projectId=wizardProject?.id;if(wizardMode==='create'){const defaults={eventName:identity.eventName,convocatoriaTime:'18:30',convocatoriaDuration:30,doorsTime:'19:30',doorsDuration:60,showStartMode:'auto',showStartTimeInput:'20:30',blocks:[]};const created=await ApiClient.saveProject({...defaults,...identity});projectId=created.data.id;}let coverKey=wizardProject?.coverKey||null;if(file){try{coverKey=await uploadCover(projectId,file);}catch(error){status.dataset.status='warning';status.textContent=`Proyecto guardado sin portada: ${error.message}`;}}await ApiClient.updateProjectIdentity(projectId,{...identity,coverKey});closeWizard();await loadProjectSelector();const project=projectsCache.find(item=>item.id===projectId);if(project){if(wizardMode==='edit'&&currentProject===project.id){currentProjectData=project;currentProjectName=project.eventName;applyProjectIdentity(project);if(window.app?.currentProjectId===project.id)document.getElementById('eventName').value=project.eventName;updateProjectUI();if(currentRoute==='summary')await loadSummary();}else await openProject(project);}}catch(error){status.dataset.status='error';status.textContent=error.message||'No se pudo guardar el proyecto.';}finally{save.disabled=false;save.removeAttribute('aria-busy');}}

  function confirmAction(title,text,action){const modal=document.getElementById('confirmModal'),copy=document.getElementById('confirmText'),button=document.getElementById('confirmAccept');document.getElementById('confirmTitle').textContent=title;copy.textContent=text;copy.dataset.status='';button.textContent='Confirmar';button.disabled=false;button.removeAttribute('aria-busy');button.onclick=async()=>{button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='Procesando…';modal.querySelectorAll('[data-cancel-confirm]').forEach(node=>node.setAttribute('aria-disabled','true'));try{await action();modal.hidden=true;}catch(error){copy.textContent=error.message||'No se pudo completar la acción. Puedes reintentarlo.';copy.dataset.status='error';button.disabled=false;button.removeAttribute('aria-busy');button.textContent='Reintentar';modal.querySelectorAll('[data-cancel-confirm]').forEach(node=>node.removeAttribute('aria-disabled'));}finally{if(modal.hidden){button.disabled=false;button.removeAttribute('aria-busy');button.textContent='Confirmar';modal.querySelectorAll('[data-cancel-confirm]').forEach(node=>node.removeAttribute('aria-disabled'));}}};modal.hidden=false;}
  async function requestPasswordReset(projectId,userId){
    confirmAction('Solicitar restablecimiento','Enviaremos un enlace al correo asociado. Nunca podremos ver su contraseña.',async()=>{
      if(userId){await Auth.api(`/api/projects/${encodeURIComponent(projectId)}/members/${encodeURIComponent(userId)}/password-reset`,{method:'POST'});return;}
      const user=await Auth.currentUser();if(!user?.email)throw new Error('No se pudo identificar el correo de la sesión.');await Auth.forgotPassword(user.email);
    });
  }
  async function projectAction(action,project){if(!project)return;if(action==='edit')openWizard('edit',project);if(action==='duplicate'){await ApiClient.duplicateProject(project.id);await loadProjectSelector();}if(action==='delete')confirmAction('Eliminar evento',`Se eliminará “${project.eventName}”. Esta acción no se puede deshacer.`,async()=>{const deletedId=project.id;await ApiClient.deleteProject(deletedId);projectsCache=projectsCache.filter(item=>item.id!==deletedId);const wasActive=currentProject===deletedId;if(wasActive){currentProject='';currentProjectData=null;currentProjectName='Elige tu evento';}if(wasActive){await navigate('projects',true);}else{await loadProjectSelector();const quota=document.getElementById('projectQuota');if(quota){quota.dataset.status='success';quota.textContent='Evento eliminado correctamente.';setTimeout(()=>{if(quota.dataset.status==='success')loadProjectSelector();},1800);}}});}

  async function loadSummary(){
    const id=currentProject, generation=navigationGeneration;
    if(!id)return;
    for(const key of ['overviewTimes','overviewPreparation','overviewReview'])document.getElementById(key).replaceChildren();
    document.getElementById('overviewTitle').textContent='Cargando evento…';
    try {
      const project=await ApiClient.getProject(id);
      if(id!==currentProject || currentRoute!=='summary' || generation!==navigationGeneration)return;
      currentProjectData=project;currentProjectName=project.eventName;
      applyProjectIdentity(project);updateProjectUI();
      await SummaryView.start(project);
    } catch(error) {
      if(id!==currentProject || currentRoute!=='summary' || generation!==navigationGeneration)return;
      document.getElementById('overviewError').textContent='No disponible. '+error.message;
      const retry=document.createElement('button');retry.type='button';retry.className='btn btn-secondary';retry.textContent='Reintentar';retry.onclick=loadSummary;document.getElementById('overviewError').append(retry);
      for(const key of ['overviewLive','overviewTeam'])document.getElementById(key).textContent='No disponible';
    }
  }
  function memberRow(member,manageable){const profile=member.profiles||{},name=`${profile.first_name||''} ${profile.last_name||''}`.trim()||profile.email||'Usuario',initials=name.split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase();const owner=member.role==='owner';return `<div class="team-row"><span class="member-avatar">${esc(initials)}</span><div><strong>${esc(name)}</strong><small>${esc(profile.email||'')}</small></div><span class="member-date">${member.created_at?new Date(member.created_at).toLocaleDateString('es-CL'):'—'}</span>${manageable&&!owner?`<select class="team-role-select" data-member-role="${esc(profile.id)}"><option value="editor" ${member.role==='editor'?'selected':''}>Director</option><option value="viewer" ${member.role==='viewer'?'selected':''}>Observador</option></select><button class="team-remove" data-remove-member="${esc(profile.id)}" type="button">Remover</button><button class="team-reset" data-reset-member="${esc(profile.id)}" type="button">Solicitar restablecimiento</button>`:`<span class="shell-role">${roleLabel(member.role)}</span>`}</div>`;}
  async function loadTeam(){const generation=navigationGeneration,project=currentProject;const status=document.getElementById('shellTeamStatus'),membersBox=document.getElementById('shellMembers'),invitesBox=document.getElementById('shellInvitations');if(!currentProject)return navigate('projects',true);const manageable=canManage(currentProjectData);document.getElementById('shellInvite').hidden=!manageable;try{const [members,invitations]=await Promise.all([Auth.api(`/api/projects/${encodeURIComponent(currentProject)}/members`),manageable?Auth.api(`/api/projects/${encodeURIComponent(currentProject)}/invitations`):Promise.resolve({data:[]})]);if(generation!==navigationGeneration||project!==currentProject)return;status.textContent=manageable?'Administra accesos y permisos de este proyecto.':'Puedes consultar el equipo asignado a este proyecto.';membersBox.innerHTML=(members.data||[]).map(member=>memberRow(member,manageable)).join('')||emptyState('Tu equipo empieza aquí','Invita a una persona como Director u Observador.',manageable?'<button class="btn btn-secondary" type="button" data-open-invite>Invitar persona</button>':'');const deliveryLabel={sent:'Correo enviado',pending:'Pendiente de entrega',failed:'No entregado',not_configured:'Pendiente de configuración'};invitesBox.innerHTML=manageable?(invitations.data||[]).map(invite=>`<div class="team-row invitation-row"><span class="member-avatar">${invite.role==='editor'?'D':'O'}</span><div><strong>${esc(invite.email)}</strong><small>${roleLabel(invite.role)} · vence ${new Date(invite.expires_at).toLocaleDateString('es-CL')} · ${deliveryLabel[invite.delivery_status]||'Estado no disponible'}</small></div><span class="invite-status status-${invite.effective_status}">${esc(invite.effective_status)}</span>${invite.effective_status==='pending'?`<button type="button" class="team-remove" data-revoke-invite="${invite.id}">Revocar</button>`:''}</div>`).join('')||emptyState('Todo al día','No hay invitaciones pendientes en este proyecto.'):'<p class="shell-muted">Solo el propietario administra invitaciones.</p>';}catch(error){if(generation!==navigationGeneration||project!==currentProject)return;status.textContent=error.message;status.dataset.status='error';}}

  const formatClp=value=>new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0}).format(Number(value)||0);
  function metricBars(items,labelKey='name') { const rows=Array.isArray(items)?items:[]; const max=Math.max(1,...rows.map(item=>Number(item.count)||0)); return rows.map(item=>`<div class="metric-bar"><div><span>${esc(item[labelKey]||'Sin nombre')}</span><strong>${Number(item.count)||0}</strong></div><i style="--metric-width:${Math.max(2,Math.round((Number(item.count)||0)*100/max))}%"></i></div>`).join('')||'<p class="shell-muted">Aún no hay datos para mostrar.</p>'; }
  function renderPASSLINKMetrics(metrics){document.getElementById('metricsDashboard').hidden=false;document.getElementById('metricIssued').textContent=Number(metrics.issued)||0;document.getElementById('metricChecked').textContent=`${Number(metrics.checkedIn)||0} acreditadas`;document.getElementById('metricRevenue').textContent=formatClp(metrics.grossSalesClp);document.getElementById('metricPayments').textContent=`${Number(metrics.approvedTickets)||0} ventas aprobadas · ${Number(metrics.pendingPayments)||0} pendientes`;document.getElementById('metricOccupancy').textContent=`${Number(metrics.occupancyPercent)||0}%`;document.getElementById('metricCapacity').textContent=metrics.capacity?`${metrics.issued} de ${metrics.capacity} entradas`:'Sin aforo definido';document.getElementById('metricPending').textContent=Number(metrics.pendingAttendance)||0;document.getElementById('metricTicketTypes').innerHTML=metricBars((metrics.ticketTypes||[]).map(item=>({...item,count:item.issued})));document.getElementById('metricZones').innerHTML=metricBars((metrics.zones||[]).map(item=>({name:item.zone,count:item.count})));}
  let metricsRequest = null;
  async function loadMetrics(){
    if(!currentProject)return navigate('projects',true);
    const project=currentProject,generation=navigationGeneration;
    if(metricsRequest?.project===project&&metricsRequest.generation===generation)return;
    const request={project,generation};
    metricsRequest=request;
    const active=()=>metricsRequest===request&&currentProject===project&&currentRoute==='metrics'&&navigationGeneration===generation;
    const status=document.getElementById('metricsStatus'),connector=document.getElementById('ticketeraConnector'),dashboard=document.getElementById('metricsDashboard'),refresh=document.getElementById('metricsRefresh');
    refresh.disabled=true;refresh.textContent='Consultando…';
    status.dataset.status='';status.textContent='Consultando conexión con PASSLINK…';connector.innerHTML='';dashboard.hidden=true;
    try{
      const connectionResult=await Auth.api(`/api/projects/${encodeURIComponent(project)}/integrations/ticketera`);
      if(!active())return;
      const connection=connectionResult.data;
      if(!connection){
        status.textContent=connectionResult.configured?'Consultando eventos de PASSLINK…':'PASSLINK todavía no está configurada en el servidor.';
        if(connectionResult.manageable&&connectionResult.configured){
          const eventsResult=await Auth.api(`/api/integrations/ticketera/events?project=${encodeURIComponent(project)}`);
          if(!active())return;
          if(!Array.isArray(eventsResult.data))throw new Error('PASSLINK devolvió un catálogo incompatible.');
          if(!eventsResult.data.length){status.textContent='No hay eventos disponibles en PASSLINK.';return;}
          const options=eventsResult.data.map(event=>`<option value="${esc(event.id)}">${esc(event.name)}${event.date?` · ${dateLabel(event.date)}`:''}</option>`).join('');
          status.textContent='Selecciona el evento equivalente en PASSLINK.';
          connector.innerHTML=`<label class="form-label" for="ticketeraEventSelect">Evento en PASSLINK</label><div class="ticketera-connect-row"><select class="form-control" id="ticketeraEventSelect"><option value="">Selecciona un evento</option>${options}</select><button class="btn btn-primary" id="ticketeraConnect" type="button">Conectar</button></div>`;
        }else if(connectionResult.configured){status.textContent='El propietario o administrador debe conectar un evento de PASSLINK.';}
        return;
      }
      connector.innerHTML=`<div class="ticketera-connected"><div><span class="shell-eyebrow">Conectado con</span><strong>${esc(connection.external_event_name)}</strong><small>${connection.last_synced_at?`Última actualización ${new Date(connection.last_synced_at).toLocaleString('es-CL')}`:'Esperando primera actualización'}</small></div>${connectionResult.manageable?'<button class="btn btn-secondary" id="ticketeraDisconnect" type="button" disabled>Desconectar</button>':''}</div>`;
      const metricsResult=await Auth.api(`/api/projects/${encodeURIComponent(project)}/metrics/ticketera`);
      if(!active())return;
      const values=metricsResult.data;
      if(!values||!['issued','checkedIn','grossSalesClp','approvedTickets','pendingPayments','occupancyPercent','capacity','pendingAttendance'].every(key=>typeof values[key]==='number'&&Number.isFinite(values[key])&&values[key]>=0)||!Array.isArray(values.ticketTypes)||!Array.isArray(values.zones))throw new Error('PASSLINK no entregó métricas válidas.');
      renderPASSLINKMetrics(metricsResult.data);
      const syncLabel=connector.querySelector('small');
      if(syncLabel&&metricsResult.connection?.last_synced_at)syncLabel.textContent=`Última actualización ${new Date(metricsResult.connection.last_synced_at).toLocaleString('es-CL')}`;
      status.dataset.status='success';status.textContent='Métricas sincronizadas con PASSLINK.';
    }catch(error){
      if(!active())return;
      dashboard.hidden=true;
      status.dataset.status=error.code==='FEATURE_DISABLED'?'warning':'error';
      if(error.code==='FEATURE_DISABLED')connector.innerHTML='<a class="btn btn-primary" href="/#planes">Ver planes con PASSLINK</a>';
      status.textContent=(error.message||'No pudimos cargar las métricas de PASSLINK.')+(error.requestId?` Referencia: ${error.requestId}`:'');
    }finally{
      if(active()){
        refresh.disabled=false;refresh.textContent='Actualizar';
        const disconnect=connector.querySelector('#ticketeraDisconnect');if(disconnect)disconnect.disabled=false;
      }
      if(metricsRequest===request)metricsRequest=null;
    }
  }

  function ensureThemeControl(){const panel=document.querySelector('#view-settings .shell-form-panel');if(!panel||document.getElementById('shellVisualTheme'))return;const group=document.createElement('div');group.className='form-group theme-control-group';group.innerHTML=`<label class="form-label" for="shellVisualTheme">Estilo del espacio de trabajo</label><select id="shellVisualTheme" class="form-control"><option value="">Claro · Predeterminado</option>${Object.entries(visualThemes).map(([key,theme])=>`<option value="${key}">${theme.label} · ${theme.description}</option>`).join('')}</select><small class="shell-muted">La landing mantiene su identidad pública. Este estilo solo cambia el espacio autenticado.</small>`;const actions=panel.querySelector('.shell-actions');panel.querySelector('.grid-2')?.insertAdjacentElement('afterend',group);if(actions){const button=document.createElement('button');button.className='btn btn-secondary';button.id='shellApplyTheme';button.type='button';button.textContent='Aplicar estilo';actions.appendChild(button);const feedback=document.createElement('small');feedback.id='shellThemeFeedback';feedback.className='shell-muted';feedback.setAttribute('role','status');actions.appendChild(feedback);button.addEventListener('click',async()=>{if(!currentProject||!currentProjectData)return;button.disabled=true;button.setAttribute('aria-busy','true');feedback.textContent='Guardando estilo…';try{const visualTheme=document.getElementById('shellVisualTheme').value;const identity={eventName:currentProjectData.eventName||currentProjectName,projectType:currentProjectData.projectType||'other',eventDate:currentProjectData.eventDate||'',location:currentProjectData.location||'',accentColor:currentProjectData.accentColor||'blue',visualTheme};await ApiClient.updateProjectIdentity(currentProject,identity);currentProjectData={...currentProjectData,visualTheme:visualTheme||null};projectsCache=projectsCache.map(project=>project.id===currentProject?{...project,visualTheme:visualTheme||null}:project);applyProjectIdentity(currentProjectData);feedback.dataset.status='success';feedback.textContent='Estilo aplicado correctamente.';}catch(error){feedback.dataset.status='error';feedback.textContent=error.message||'No se pudo aplicar el estilo.';}finally{button.disabled=false;button.removeAttribute('aria-busy');}});}}
  function updateProjectUI(){const name=document.getElementById('navProjectName');if(name){name.textContent=currentProjectName;name.hidden=currentRoute==='projects'||!currentProject;name.title=`Cambiar de evento · ${currentProjectName}`;}document.body.dataset.projectId=currentProject||'';window.dispatchEvent(new CustomEvent('tshow:project-context',{detail:{projectId:currentProject||''}}));['shellLiveLink','summaryLiveLink','scheduleLive'].forEach(id=>{const link=document.getElementById(id);if(link)link.href=currentProject?`live.html?project=${encodeURIComponent(currentProject)}`:'live.html';});const title=document.getElementById('summaryProjectTitle');if(title)title.textContent=currentProjectName;const input=document.getElementById('shellEventName');if(input)input.value=currentProjectName==='Elige tu evento'?'':currentProjectName;const pid=document.getElementById('shellProjectId');if(pid)pid.textContent=currentProject?'Identificador interno protegido':'Sin evento seleccionado';const role=document.getElementById('workspaceUserRole');if(role)role.textContent=currentProjectData?roleLabel(currentProjectData.permission):'Cuenta T-Show';ensureThemeControl();const themeSelect=document.getElementById('shellVisualTheme');if(themeSelect)themeSelect.value=currentProjectData?.visualTheme||'';document.body.classList.toggle('project-selector-active',currentRoute==='projects');}
