  async function loadProduction(){
    const status=document.getElementById('operationalSyncStatus'); if(!currentProject)return;
    const activeKey=document.querySelector('[data-operational-tab].is-active')?.dataset.operationalTab||'readiness';
    try{const result=await ApiClient.request(`/projects/${encodeURIComponent(currentProject)}/production`);operationalOfflineMode=false;operationalData=result.data||{};operationalData.readiness=operationalData.readiness||[];operationalData.checklist=operationalData.tasks||[];if(activeKey!=='readiness'){const endpoint={checklist:'tasks',cues:'technical-cues',artists:'artists',notices:'notices',adjustments:'timing-adjustments',rehearsals:'rehearsals'}[activeKey];if(endpoint){const extra=await ApiClient.request(`/projects/${encodeURIComponent(currentProject)}/${endpoint}`);operationalData[activeKey==='checklist'?'checklist':activeKey]=extra.data||[];}}status.textContent=`Sincronizado · ${new Date(result.serverTime||Date.now()).toLocaleTimeString('es-CL')}`;operationalPanel(activeKey);}
    catch(error){try{const cached=await window.TShowOffline?.read(`${currentAccount?.id||'account'}:${currentProject}`);if(cached?.value&&Date.now()-new Date(cached.savedAt).getTime()<86400000){operationalOfflineMode=true;operationalData=cached.value;status.textContent=`Sin conexión · solo consulta · última validación ${new Date(cached.savedAt).toLocaleString('es-CL')}`;operationalPanel('readiness');return;}}catch(_){}status.dataset.status='error';status.textContent=error.message||'No se pudo cargar Producción.';document.getElementById('operationalPanel').innerHTML=error.code==='feature_disabled'?'<div class="operational-empty"><h2>Producción aún no está habilitada para este evento</h2><p class="shell-muted">La habilitación es por evento y no cambia precios ni permisos generales.</p><button class="btn btn-primary" data-operational-enable>Habilitar para este evento</button></div>':'<p class="shell-message" data-status="error">La vista operativa no está disponible en este momento.</p>';}
  }
  async function navigate(route,push){const generation=++navigationGeneration;SummaryView.stop();if(!routes.includes(route))route='projects';if(route!=='projects'){if(!currentProject){route='projects';push=true;}else{if(!projectsCache.length)await loadProjects().catch(()=>{});if(generation!==navigationGeneration)return;currentProjectData=projectsCache.find(project=>project.id===currentProject)||null;if(!currentProjectData){currentProject='';currentProjectName='Elige tu evento';route='projects';push=true;}}}if(generation!==navigationGeneration)return;const old=views[currentRoute];if(old&&old!==views[route]){old.classList.remove('is-active');old.classList.add('is-leaving');setTimeout(()=>old.classList.remove('is-leaving'),150);}currentRoute=route;views[route].classList.add('is-active');document.querySelectorAll('.workspace-nav [data-route]').forEach(link=>{if(link.dataset.route===route)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});const tools=document.getElementById('workspaceTools');if(tools)tools.classList.toggle('is-active',['metrics','files','settings'].includes(route));document.title=`T-Show · ${labels[route]}`;if(push)history.pushState({route},'',routeUrl(route));updateProjectUI();setViewLoading(route,true,`Cargando ${labels[route]||'vista'}…`);try{if(route==='projects')await loadProjectSelector();if(route==='summary')await loadSummary();if(route==='metrics')await loadMetrics();if(route==='team')await loadTeam();if(route==='production')await loadProduction();if(route==='files')await window.ProjectFiles.load();if(route==='notes'){notesLoadedProject='';await loadNotes();if(generation===navigationGeneration)notesLoadedProject=currentProject;}}finally{if(generation===navigationGeneration)setViewLoading(route,false);}if(generation!==navigationGeneration)return;scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}

